                          fit: BoxFit.cover,
                          scanWindow: scanWindow,
                          tapToFocus: true,
                          onDetect: _detect,
                          overlayBuilder: (context, _) =>
                              const RawMaterialScannerGuide(),
                        );
                      },
                    ),
            ),
            DecoratedBox(
              decoration: BoxDecoration(
                color: scheme.surface,
                border: Border(top: BorderSide(color: scheme.outlineVariant)),
